module \ener_relay.cs_sync (clk, rst, stage2, cs_n);
  input clk;
  wire clk;
  input rst;
  wire rst;
  output stage2;
  reg stage2 = 1'h1;
  input cs_n;
  wire cs_n;
  wire \$signal ;
  reg stage0 = 1'h1;
  reg stage1 = 1'h1;
  always @(posedge clk)
    stage0 <= cs_n;
  always @(posedge clk)
    stage1 <= stage0;
  always @(posedge clk)
    stage2 <= stage1;
  assign \$signal  = stage2;
endmodule

module \ener_relay.reset_sync (clk, rst, stage2, soft_reset);
  input clk;
  wire clk;
  input rst;
  wire rst;
  output stage2;
  reg stage2 = 1'h0;
  input soft_reset;
  wire soft_reset;
  wire soft_reset_sync;
  reg stage0 = 1'h0;
  reg stage1 = 1'h0;
  always @(posedge clk)
    stage0 <= soft_reset;
  always @(posedge clk)
    stage1 <= stage0;
  always @(posedge clk)
    stage2 <= stage1;
  assign soft_reset_sync = stage2;
endmodule

module \ener_relay.sck_sync (clk, rst, stage2, sck);
  input clk;
  wire clk;
  input rst;
  wire rst;
  output stage2;
  reg stage2 = 1'h0;
  input sck;
  wire sck;
  wire \$signal ;
  reg stage0 = 1'h0;
  reg stage1 = 1'h0;
  always @(posedge clk)
    stage0 <= sck;
  always @(posedge clk)
    stage1 <= stage0;
  always @(posedge clk)
    stage2 <= stage1;
  assign \$signal  = stage2;
endmodule

module \ener_relay.si_sync (clk, rst, stage2, mosi);
  input clk;
  wire clk;
  input rst;
  wire rst;
  output stage2;
  reg stage2 = 1'h0;
  input mosi;
  wire mosi;
  wire si;
  reg stage0 = 1'h0;
  reg stage1 = 1'h0;
  always @(posedge clk)
    stage0 <= mosi;
  always @(posedge clk)
    stage1 <= stage0;
  always @(posedge clk)
    stage2 <= stage1;
  assign si = stage2;
endmodule
